import 'combat_state_v4.dart';
int effectiveDelayV4({required int baseDelay,required CombatUnitV4 unit}){final speed=unit.stats.speed.clamp(80,130).toInt();var modifier=0.0;final slowed=unit.status(StatusTypeV4.slowed);if(slowed!=null)modifier+=slowed.potency==0?0.20:slowed.potency/100.0;final haste=unit.status(StatusTypeV4.haste);if(haste!=null)modifier-=haste.potency==0?0.15:haste.potency/100.0;modifier=modifier.clamp(-0.30,0.50).toDouble();return(baseDelay*100/speed*(1+modifier)).round();}
class TimelineV4{TimelineV4(this.units);final List<CombatUnitV4> units;int now=0;List<CombatUnitV4> ordered({int limit=8}){final active=units.where((u)=>!u.isKo).toList()..sort((a,b){final t=a.nextActionTime.compareTo(b.nextActionTime);if(t!=0)return t;final s=b.stats.speed.compareTo(a.stats.speed);return s!=0?s:a.id.compareTo(b.id);});return active.take(limit).toList(growable:false);}CombatUnitV4? nextActor(){final o=ordered(limit:1);if(o.isEmpty)return null;now=o.first.nextActionTime;return o.first;}void schedule(CombatUnitV4 unit,int baseDelay){unit.nextActionTime=now+effectiveDelayV4(baseDelay:baseDelay,unit:unit);}void push(CombatUnitV4 unit,int amount){if(amount>0)unit.nextActionTime+=amount;}}
